const runtime=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),research=path.join(runtime,'research-cohorts'),journal=path.join(runtime,'journal.jsonl');
const read=f=>JSON.parse(fs.readFileSync(f)),sha=b=>createHash('sha256').update(b).digest('hex');
const graph=['Cargo.toml','Cargo.lock','build.rs','.cargo/config.toml','src/main.rs','src/money.rs','src/types.rs','src/capture.rs','src/engine.rs','src/replay.rs','src/trace.rs','src/sweep.rs','src/evaluation.rs','src/publication.rs'];
const h=createHash('sha256'),sourceHashes={};for(const f of graph){const b=fs.readFileSync(path.join('backend-rust',f)),name=Buffer.from(f),n=Buffer.alloc(8);n.writeBigUInt64LE(BigInt(name.length));h.update(n).update(name);n.writeBigUInt64LE(BigInt(b.length));h.update(n).update(b);sourceHashes['backend-rust/'+f]=sha(b);}const engineHash=h.digest('hex');
