const normal=p=>{const{fillClockPolicy,blockedPreLatencySnapshots,...x}=p;return x;},key=c=>[c.strategy,c.scenario.id,c.exitPolicy].join('/'),prior=new Map(legacy.evaluation.scorecards.map(c=>[key(c),c]));
