let clocks=0;for(const c of strict.evaluation.scorecards)for(const f of c.fills){const q=f.sourceClock;assert.equal(q.policy,'independent_request_latency_v2');for(const k of ['decisionSequence','decisionSourceNs','fillSequence','fillSourceNs'])assert.equal(typeof q[k],'string');assert(q.requestStartedAt>=q.decisionAt+q.minimumLatencyMs);assert.equal(q.receivedAt,f.at);assert(q.receivedAt>=q.requestStartedAt);assert(q.fillSequence!==q.decisionSequence||q.fillSourceNs!==q.decisionSourceNs);clocks++;}
const changed=strict.evaluation.scorecards.filter(c=>JSON.stringify(normal(c.point))!==JSON.stringify(prior.get(key(c)).point));
const sealed=()=>{const fd=fs.openSync(journal,'r');try{const size=fs.fstatSync(fd).size,amount=Math.min(size,16*1024*1024),b=Buffer.alloc(amount);assert.equal(fs.readSync(fd,b,0,amount,size-amount),amount);const last=b.lastIndexOf(10);assert(last>=0);return size-amount+last+1;}finally{fs.closeSync(fd);}};
const endByte=sealed(),sourceHash=await sourcePrefixHash(journal,endByte),futureDir=path.join(research,'baal-dip-request-clock-20261004-v2'),futureFile=path.join(futureDir,'declaration.json'),futureBytes=fs.readFileSync(futureFile),frozen=read('data/native-request-clock-declaration-20261004.json');assert.equal(sha(futureBytes),frozen.receipt.declarationHash);
t=performance.now();const futureOut=path.join(futureDir,randomUUID()+'.json'),future=await evaluateNativeCapture({journal,declaration:futureFile,endByte,expectedSha:sourceHash,out:futureOut,workers:8,executable});const futureWallMs=performance.now()-t;
assert.equal(future.capture.engine_hash,engineHash);assert.equal(future.evaluation.evaluationStart,frozen.receipt.tradingStartsAfter);
for(const c of future.evaluation.scorecards)for(const f of c.fills){const q=f.sourceClock;assert(q.decisionAt>Date.parse(frozen.receipt.tradingStartsAfter));assert(q.requestStartedAt>=q.decisionAt+q.minimumLatencyMs);assert.equal(q.receivedAt,f.at);}
for(const out of [path.join(work,'legacy.json'),path.join(work,'strict.json'),futureOut]){const r=read(out+'.receipt.json');assert.equal(r.binaryHash,binaryHash);assert.equal(r.engineHash,engineHash);assert.equal(r.outputHash,sha(fs.readFileSync(out)));}
